using System;using System.IO;using System.Linq;using System.Reflection;using System.Collections.Generic;using System.Windows;using System.Windows.Controls;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Threading;using System.Web.Script.Serialization;using D=System.Drawing;
class LabelEditTests {
 static int checks,failures;static void Check(bool v,string n){checks++;Console.WriteLine((v?"PASS ":"FAIL ")+n);if(!v)failures++;}static object Get(object o,string n){return o.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).GetValue(o);}static object Call(object o,string n,params object[] a){return o.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic|BindingFlags.Public).Invoke(o,a);}static IEnumerable<DependencyObject> Tree(DependencyObject o){yield return o;for(int i=0;i<VisualTreeHelper.GetChildrenCount(o);i++)foreach(var v in Tree(VisualTreeHelper.GetChild(o,i)))yield return v;}static T Named<T>(DependencyObject w,string n)where T:DependencyObject{Pump();return Tree(w).OfType<T>().First(c=>System.Windows.Automation.AutomationProperties.GetName(c)==n);}static void Pump(){var frame=new DispatcherFrame();var timer=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(100)};timer.Tick+=(s,e)=>{timer.Stop();frame.Continue=false;};timer.Start();Dispatcher.PushFrame(frame);}static void Click(Window w,string n){Tree(w).OfType<Button>().First(b=>Convert.ToString(b.Content)==n).RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump();}static void Shot(Window w,string path){w.UpdateLayout();var root=(FrameworkElement)w.Content;var b=new RenderTargetBitmap((int)root.ActualWidth,(int)root.ActualHeight,96,96,PixelFormats.Pbgra32);b.Render(root);var e=new PngBitmapEncoder();e.Frames.Add(BitmapFrame.Create(b));using(var f=File.Create(path))e.Save(f);}

 [STAThread]static int Main(string[] args){Directory.CreateDirectory(args[0]);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};Window pet=null;try{
 pet=(Window)Activator.CreateInstance(typeof(ConanPet),true);var assistant=(AssistantRuntime)Get(pet,"assistant");assistant.Config.Monitor.Quota.Enabled=false;((VoiceRuntime)Get(pet,"voices")).Settings.Enabled=false;pet.Show();Pump();((System.Threading.Timer)Get(pet,"assistantTimer")).Change(-1,-1);((DispatcherTimer)Get(pet,"ticker")).Stop();((DispatcherTimer)Get(pet,"skillTicker")).Stop();Call(pet,"OpenTerminal");var w=(TerminalWindow)Get(pet,"terminal");
 foreach(string mode in new[]{"original","soft","neon"})foreach(string theme in new[]{"a","b"}){
 VisualEffects.SetMode(mode);w.SetTheme(theme,false);w.ShowPage("任务栏外观");Click(w,"显示内容");var box=Named<TextBox>(w,"标签-codex7d");box.Focus();Check(box.Foreground is SolidColorBrush,"IME-compatible label foreground "+mode+"/"+theme);
 foreach(string text in new[]{"额度周","","7","7d","周额度","7d"}){box.Text=text;box.Select(box.Text.Length,0);Pump();Check(((MonitorConfig)Get(w,"taskbarDraft")).Appearance.Item("codex7d").Label==text,"label draft edit "+mode+"/"+theme+"/"+text);}
 Check(Tree(w).OfType<TextBox>().All(t=>t.Foreground is SolidColorBrush),"all loaded text editors use solid foreground "+mode+"/"+theme);
 Click(w,"应用并保存任务栏外观");Check(assistant.Config.Monitor.Appearance.Item("codex7d").Label=="7d","save label "+mode+"/"+theme);
 var combo=new ComboBox{IsEditable=true};combo.Items.Add("中文");var password=new PasswordBox();var panel=new StackPanel();panel.Children.Add(combo);panel.Children.Add(password);var extra=new Window{Content=panel};extra.Resources.MergedDictionaries.Add(TerminalAppearance.Resources());TerminalAppearance.Palette(extra.Resources,theme);TerminalAppearance.BindTree(panel);extra.Show();Pump();VisualEffects.Apply(extra);combo.ApplyTemplate();var edit=combo.Template.FindName("PART_EditableTextBox",combo) as TextBox;Check(edit!=null&&edit.Foreground is SolidColorBrush,"editable combo input compatible "+mode+"/"+theme);Check(password.Foreground is SolidColorBrush,"password input compatible "+mode+"/"+theme);Check(mode=="original"||extra.Resources["DeskText"] is LinearGradientBrush,"decorative text gradients preserved "+mode+"/"+theme);extra.Close();
 }
 var reloaded=new AssistantRuntime(AppDomain.CurrentDomain.BaseDirectory);Check(reloaded.Config.Monitor.Appearance.Item("codex7d").Label=="7d","renamed label survives runtime reload");reloaded.Telemetry.Dispose();
 }catch(Exception e){Console.WriteLine("FAIL "+e);failures++;}finally{if(pet!=null)pet.Close();app.Shutdown();}File.WriteAllText(Path.Combine(args[0],"label-edit-results.json"),new JavaScriptSerializer().Serialize(new{checks,failures,isolated_settings=true,native_ime_candidate_ui_automated=false}));return failures==0?0:1;}
}
